inner="\nfrom pathlib import Path\nimport json,sys,numpy as np,torch\nfrom torch import nn\nfrom torch.nn import functional as F\nfrom experiments.pamf_phase1_flow import experiment as core,physical_rich_router_experiment as g,feature_conditioned_experiment as fs\nroot=Path('/home/szu2070436088/2510044040/CV-SincNet');torch.set_num_threads(2)\nmodels=g.load_models(root,'cpu');teacher,contract,dura,boundary,feature,_,_,_=models;cache,clean,roles=core.data(root,contract)\nfrom leo_practical.channel import Config,receiver_for_session,stable_seed,normalize_input\nfrom leo_practical.residual import ResidualChannel\nids=np.load(cache/'train/physical_ids.npy',allow_pickle=False);rx=np.load(cache/'train/rx.npy',allow_pickle=False);day=np.load(cache/'train/day.npy',allow_pickle=False)\n# Exclude IDs used by the earlier 8,192-ID consensus probe and 4,096-ID\n# diffusion pilots. Other historical source diagnostics may still overlap.\nspecs=(('L_s',2048,1024,2048),('U_s',6144,3072,6144));previous={}\nfor seed,column in ((2026110251,1),(2026110301,2)):\n gen=np.random.default_rng(seed)\n for spec in specs:\n  role=spec[0];available=np.flatnonzero(roles==role);previous.setdefault(role,[]).append(gen.choice(available,size=spec[column],replace=False))\nrng=np.random.default_rng(2026110321);groups=[]\nfor role,_,__,take in specs:\n available=np.flatnonzero(roles==role);available=np.setdiff1d(available,np.unique(np.concatenate(previous[role])),assume_unique=True)\n assert len(available)>=take;groups.append(np.sort(rng.choice(available,size=take,replace=False)))\nfixed=np.concatenate(groups);assert len(fixed)==len(np.unique(fixed))==8192\nsource_rx=rx[fixed];source_day=day[fixed];split=np.full(len(fixed),-1,dtype=np.int64)\nsplit[np.isin(source_rx,[1,3,4])&np.isin(source_day,[1,2])]=0\nsplit[np.isin(source_rx,[4,6])&(source_day==3)]=1\nsplit[(source_rx==8)&(source_day==3)]=2\nassert all(int((split==i).sum())>200 for i in range(3))\nkeep=split==2;fixed=fixed[keep];source_rx=source_rx[keep];source_day=source_day[keep];split=split[keep];assert len(fixed)>400\nviews=('clean','practical_low_suburban','practical_mid_urban','practical_low_urban');namespace='phase1-source-conditional-diffusion-2026110302';data={}\nwith torch.no_grad():\n for view in views:\n  if view=='clean':received=np.asarray(clean[fixed],dtype=np.float32)\n  else:\n   cfgs={snr:Config(fs_hz=25e6,fc_hz=2462e6,scenario=view,processing_route='residual',mode='post_sync',equalization_enabled=False,reference_snr_db=snr,boundary='reflect') for snr in (10.,20.,30.)}\n   received=[]\n   for position,j in enumerate(fixed):\n    pid=str(ids[j]);snr=(10.,20.,30.)[stable_seed(2026110312,'diffusion-source-hard-snr',view,pid)%3] if split[position]==0 else 30.;cfg=cfgs[snr]\n    session='rx%d:day%d:eq1'%(int(rx[j]),int(day[j]));hw=receiver_for_session(cfg,2026110303,session)\n    v=np.asarray(clean[j],dtype=np.float64);signal,_=normalize_input(v[0]+1j*v[1]);result,meta=ResidualChannel(cfg,stable_seed(2026110302,namespace,view,pid),hw).process(signal)\n    assert np.isfinite(result).all() and not meta['channel_equalization_applied'];received.append(np.stack((result.real,result.imag)).astype(np.float32))\n   received=np.stack(received)\n  anchors=[];rawp=[];basep=[]\n  for start in range(0,len(fixed),32):\n   x=core.tensor(received[start:start+32],'cpu');a=dura(x);anchors.append(a.cpu())\n   rawp.append(F.softmax(teacher.classify_features(teacher.features(x)),1).cpu())\n   basep.append(F.softmax(teacher.classify_features(teacher.features(a)),1).cpu())\n  data[view]=dict(received=core.tensor(received,'cpu'),anchor=torch.cat(anchors),rawp=np.from_dlpack(torch.cat(rawp).contiguous()),basep=np.from_dlpack(torch.cat(basep).contiguous()))\n  print('SCALED_DIFFUSION_SOURCE_BASELINES_FIXED',view,flush=True)\nprint('ALL_SOURCE_BASELINES_FIXED_BEFORE_SOURCE_LABELS',flush=True)\nclass Block(nn.Module):\n def __init__(self,dilation):\n  super().__init__();self.a=nn.Conv1d(32,32,3,padding=dilation,dilation=dilation);self.b=nn.Conv1d(32,32,3,padding=1)\n def forward(self,x):return x+.2*self.b(F.gelu(self.a(F.gelu(x))))\n\nclass NoiseNet(nn.Module):\n def __init__(self):\n  super().__init__();self.enter=nn.Conv1d(7,32,5,padding=2);self.blocks=nn.Sequential(Block(1),Block(2),Block(4));self.exit=nn.Conv1d(32,2,3,padding=1)\n def forward(self,z,a,x,sigma):\n  t=sigma[:,None,None].expand(-1,1,z.shape[-1]);return self.exit(self.blocks(self.enter(torch.cat((z,a,x,t),1))))\n\n\nexpected=json.load(sys.stdin);q=nn.Sequential(nn.Linear(698,256),nn.GELU(),nn.Linear(256,6));q.load_state_dict({k:torch.tensor(v,dtype=torch.float32) for k,v in expected['model_state'].items()},strict=True);q.eval()\nmean=np.asarray(expected['feature_mean'],dtype=np.float32);std=np.asarray(expected['feature_std'],dtype=np.float32);predictions={};phases=np.arange(12,dtype=np.float64)*(2*np.pi/12)\nwith torch.no_grad():\n for view in views:\n  parts={k:[] for k in ('base','qclass','qconfidence','experts','phase_probs','ratio')}\n  for start in range(0,len(fixed),32):\n   x=data[view]['received'][start:start+32];a=data[view]['anchor'][start:start+32];fa=teacher.features(a);base=teacher.classify_features(fa)\n   outputs=(x,a,boundary(x,a),feature(x,a,fa,base));emb=(teacher.features(x),fa,teacher.features(outputs[2]),teacher.features(outputs[3]));probs=torch.stack([F.softmax(teacher.classify_features(z),1) for z in emb],1)\n   energy=torch.stack((x.square().mean((1,2)).clamp_min(1e-8).log(),a.square().mean((1,2)).clamp_min(1e-8).log()),1)\n   def spectrum(z):\n    wave=torch.complex(z[:,0,:],z[:,1,:]);power=torch.fft.fft(wave,dim=-1).abs().square().reshape(len(z),16,16).mean(-1);return power/power.sum(1,keepdim=True).clamp_min(1e-8)\n   feats=torch.cat((probs.reshape(len(x),24),energy,*[F.normalize(z,dim=1) for z in emb],spectrum(x),spectrum(x-a)),1);assert feats.shape==(len(x),698)\n   scaled=np.clip((np.from_dlpack(feats.contiguous())-mean)/std,-10,10).astype(np.float32);qp=F.softmax(q(core.tensor(scaled,'cpu')),1)\n   z=torch.complex(a[:,0,:],a[:,1,:]);rotated=[]\n   for phase in phases:\n    w=z*complex(np.cos(phase),np.sin(phase));v=torch.stack((w.real,w.imag),1);rotated.append(F.softmax(teacher.classify_features(teacher.features(v)),1).cpu())\n   ratio=((x-a).square().mean((1,2))/(x.square().mean((1,2)).clamp_min(1e-8))).sqrt()\n   parts['base'].append(probs[:,1].argmax(1).cpu());parts['qclass'].append(qp.argmax(1).cpu());parts['qconfidence'].append(qp.max(1).values.cpu());parts['experts'].append(probs.argmax(2).cpu());parts['phase_probs'].append(torch.stack(rotated,1).cpu());parts['ratio'].append(ratio.cpu())\n  predictions[view]={k:np.from_dlpack(torch.cat(v).contiguous()) for k,v in parts.items()}\n  assert np.array_equal(predictions[view]['phase_probs'][:,0,:].argmax(1),predictions[view]['base'])\n  print('PHASE_ENSEMBLE_SOURCE_PREDICTIONS_FIXED',view,flush=True)\nprint('ALL_PHASE_ENSEMBLE_SOURCE_PREDICTIONS_FIXED_BEFORE_SOURCE_LABELS',flush=True)\nlabels=fs.source_labels(root,cache,clean,roles,contract);labeled=roles[fixed]=='L_s';assert np.all(labels[fixed[~labeled]]==-1)\nref=data['clean']['rawp'];teacher_target=ref.argmax(1);valid=labeled|(ref.max(1)>=.95);target=np.where(labeled,labels[fixed],teacher_target);results=[]\nfor view in views:\n v=predictions[view];base=v['base'];qclass=v['qclass'];qconf=v['qconfidence'];p=v['phase_probs'];phasepred=p.argmax(2);n=len(base)\n # Fixed before scoring: use a phase that maximizes probability of the\n # existing high-confidence semantic class, with and without clean guard.\n desired=np.take_along_axis(p,qclass[:,None,None],axis=2).squeeze(2);choice=desired.argmax(1);candidate=phasepred[np.arange(n),choice]\n use=(qconf>=.9)&(qclass!=base)&(candidate==qclass);out=np.where(use,candidate,base)\n guarded=np.where(use&(v['ratio']>=.02),candidate,base)\n # Exploratory truth selector: never available at inference.\n oracle=(phasepred==target[:,None]).any(1);four=(v['experts']==target[:,None]).any(1);old=base==target\n row=dict(view=view,valid=int(valid.sum()),L_s=int((valid&labeled).sum()),U_pseudo=int((valid&~labeled).sum()),dura=int((valid&old).sum()),phase_oracle=int((valid&oracle).sum()),phase_oracle_beyond_four=int((valid&oracle&~four).sum()),phase_q=int((valid&(out==target)).sum()),phase_q_repairs=int((valid&~old&(out==target)).sum()),phase_q_damages=int((valid&old&(out!=target)).sum()),guarded_q=int((valid&(guarded==target)).sum()),guarded_repairs=int((valid&~old&(guarded==target)).sum()),guarded_damages=int((valid&old&(guarded!=target)).sum()),q_switches=int((valid&use).sum()),guarded_switches=int((valid&use&(v['ratio']>=.02)).sum()),L_s_dura=int((valid&labeled&old).sum()),L_s_phase_q=int((valid&labeled&(out==target)).sum()),L_s_guarded=int((valid&labeled&(guarded==target)).sum()))\n # Class votes across the physically phase-rotated candidates. If tied,\n # keep DURA whenever its class is among the tied winners.\n counts=(phasepred[:,:,None]==np.arange(6)[None,None,:]).sum(1);top=counts.max(1);winner=counts.argmax(1)\n winner=np.where(counts[np.arange(n),base]==top,base,winner);consensus={}\n for minimum in (7,9,11):\n  proposed=np.where(top>=minimum,winner,base);right=proposed==target\n  consensus[str(minimum)]=dict(correct=int((valid&right).sum()),repairs=int((valid&~old&right).sum()),damages=int((valid&old&~right).sum()),L_s_correct=int((valid&labeled&right).sum()),switches=int((valid&(proposed!=base)).sum()))\n  agree=(top>=minimum)&(winner==qclass)&(qconf>=.9);proposed_q=np.where(agree,winner,base);right_q=proposed_q==target\n  consensus[str(minimum)+'_semantic']=dict(correct=int((valid&right_q).sum()),repairs=int((valid&~old&right_q).sum()),damages=int((valid&old&~right_q).sum()),L_s_correct=int((valid&labeled&right_q).sum()),switches=int((valid&(proposed_q!=base)).sum()))\n row['consensus']=consensus;row['q_correct']=int((valid&(qclass==target)).sum());row['q_high_confident']=int((valid&(qconf>=.9)).sum());row['q_high_correct']=int((valid&(qconf>=.9)&(qclass==target)).sum())\n row['q_available_repairs']=int((valid&~old&(qclass==target)&(qconf>=.9)&(phasepred==qclass[:,None]).any(1)).sum())\n results.append(row);print('PHASE_ENSEMBLE_SOURCE_RESULT',json.dumps(row),flush=True)\nprint('SOURCE_PHASE_CONSENSUS_PROBE '+json.dumps(dict(status='SOURCE_ONLY_PHASE_CONSENSUS_PROBE',source_ids=len(fixed),results=results,phase_count=12,semantic_threshold=.9,clean_ratio_guard=.02,U_s_labels_read=0,V_reads=0,test_IQ_reads=0,predictions_before_source_labels=True,\n caveat='Phase oracle uses source targets and is not deployable. Fixed semantic gate uses only received IQ and frozen models; no validation split or hyperparameter selection is performed here. IDs exclude earlier semantic and diffusion pilot samples but may overlap other source probes; experts saw source records. Simulator is not validated real satellite data and earlier observed Phase1 test results informed exploration.'),ensure_ascii=False),flush=True)\n"
